contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public {
        bool firstSetLogFileOk;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstSetLogFileOk = false;
        } else {
            firstSetLogFileOk = true;
        }

        bool initOk;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            initOk = false;
        } else {
            initOk = true;
        }

        bool secondSetLogFileReverted;
        c.SetLogFile(_log); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            secondSetLogFileReverted = true;
        } else {
            secondSetLogFileReverted = false;
        }

        assert(firstSetLogFileOk && initOk && secondSetLogFileReverted);
    }

    receive() external payable {}
}

